def from_digits(digits, base):
    value = 0
    for digit in digits:
        value = value * base + digit
    return value


def to_digits(number, base_to):
    result = []
    while number > 0:
        number, digit = divmod(number, base_to)
        result.append(digit)
    return result[::-1] or [0]


def rebase(from_base, digits, to_base):
    if from_base < 2:
        raise ValueError('input base must be >= 2')
    if to_base < 2:
        raise ValueError('output base must be >= 2')
    digits = tuple(digits)
    if any(digit < 0 or digit >= from_base for digit in digits):
        raise ValueError('all digits must satisfy 0 <= d < input base')
    return to_digits(from_digits(digits, from_base), to_base)

