from collections import Counter

PER_BOOK = 800.0
PER_GROUP = {1: PER_BOOK, 2: 1520.0, 3: 2160.0, 4: 2560.0, 5: 3000.0}


def _total(basket):
    counts = sorted(Counter(basket).values(), reverse=True) + [0]
    groups = {size: counts[size - 1] - counts[size] for size in range(1, len(counts))}
    # A group of five and a group of three can be rearranged into two fours.
    pairs = min(groups.get(5, 0), groups.get(3, 0))
    saving = PER_GROUP[5] + PER_GROUP[3] - 2 * PER_GROUP[4]
    return sum(quantity * PER_GROUP[size] for size, quantity in groups.items()) - pairs * saving


def total(basket):
    if not basket:
        return 0
    return _total(basket)

