def find_fewest_coins(coins, target):
    if target < 0:
        raise ValueError("target can't be negative")
    unreachable = target + 1
    counts = [unreachable] * (target + 1)
    counts[0] = 0
    last_coin = [0] * (target + 1)
    denominations = sorted({coin for coin in coins if 0 < coin <= target})
    for amount in range(1, target + 1):
        for coin in denominations:
            if coin > amount:
                break
            candidate = counts[amount - coin] + 1
            if candidate < counts[amount]:
                counts[amount] = candidate
                last_coin[amount] = coin
    if counts[target] == unreachable:
        raise ValueError("can't make target with given coins")
    result = []
    while target:
        coin = last_coin[target]
        result.append(coin)
        target -= coin
    return result
